import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';

// Practical 15: Complete Student Management App with Firebase Auth and Firestore CRUD
void main() async { WidgetsFlutterBinding.ensureInitialized(); await Firebase.initializeApp(); runApp(const MaterialApp(home: AuthGate())); }
class AuthGate extends StatelessWidget { const AuthGate({super.key}); @override Widget build(BuildContext c)=>StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),builder:(context,s){if(!s.hasData)return const LoginPage();return const StudentHome();});}
class LoginPage extends StatefulWidget { const LoginPage({super.key}); @override State<LoginPage> createState()=>_LoginPageState();}
class _LoginPageState extends State<LoginPage>{final e=TextEditingController(),p=TextEditingController();String msg='';Future<void> login()async{try{await FirebaseAuth.instance.signInWithEmailAndPassword(email:e.text.trim(),password:p.text);}on FirebaseAuthException catch(x){setState(()=>msg=x.message??'Login failed');}}
Future<void> register()async{try{await FirebaseAuth.instance.createUserWithEmailAndPassword(email:e.text.trim(),password:p.text);}on FirebaseAuthException catch(x){setState(()=>msg=x.message??'Registration failed');}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Student App Login')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:e,decoration:const InputDecoration(labelText:'Email')),TextField(controller:p,obscureText:true,decoration:const InputDecoration(labelText:'Password')),ElevatedButton(onPressed:login,child:const Text('Login')),TextButton(onPressed:register,child:const Text('Register')),Text(msg)])));}
class StudentHome extends StatefulWidget { const StudentHome({super.key}); @override State<StudentHome> createState()=>_StudentHomeState();}
class _StudentHomeState extends State<StudentHome>{final n=TextEditingController(),r=TextEditingController(),co=TextEditingController();CollectionReference get students=>FirebaseFirestore.instance.collection('students');
Future<void> save([String? id])async{final data={'name':n.text,'rollNumber':r.text,'course':co.text};if(id==null)await students.add(data);else await students.doc(id).update(data);n.clear();r.clear();co.clear();}
Future<void> edit(String id,Map<String,dynamic> d)async{n.text=d['name']??'';r.text=d['rollNumber']??'';co.text=d['course']??'';await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Edit Student'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Name')),TextField(controller:r,decoration:const InputDecoration(labelText:'Roll')),TextField(controller:co,decoration:const InputDecoration(labelText:'Course'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('Cancel')),TextButton(onPressed:()async{await save(id);if(mounted)Navigator.pop(context);},child:const Text('Update'))]));}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('Students - ${FirebaseAuth.instance.currentUser?.email??''}'),actions:[IconButton(onPressed:()=>FirebaseAuth.instance.signOut(),icon:const Icon(Icons.logout))]),body:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Name')),TextField(controller:r,decoration:const InputDecoration(labelText:'Roll Number')),TextField(controller:co,decoration:const InputDecoration(labelText:'Course')),ElevatedButton(onPressed:()=>save(),child:const Text('Add Student')),Expanded(child:StreamBuilder<QuerySnapshot>(stream:students.snapshots(),builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data() as Map<String,dynamic>;return ListTile(title:Text(x['name']??''),subtitle:Text('${x['rollNumber']??''} - ${x['course']??''}'),onTap:()=>edit(d.id,x),trailing:IconButton(icon:const Icon(Icons.delete),onPressed:()=>d.reference.delete()));}).toList());}))]));}
